div.script:
var video = document.getElementById('preview');
var scanning = false;
var currentCode = null;
var tourId = <t t-js-esc="tour.id"/>;

function stopScanner() {
    scanning = false;
    video.style.display = 'none';
    if (video.srcObject) video.srcObject.getTracks().forEach(t => t.stop());
}

async function logCheckpoint(code) {
    try {
        const pos = await new Promise((res, rej) =>
            navigator.geolocation.getCurrentPosition(res, rej)
        );

        const response = await fetch('/my/patrol/checkin', {
            method: 'POST',
            headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify({
                jsonrpc: '2.0',
                params: {
                    tour_id: tourId,
                    checkpoint_code: code,
                    lat: pos.coords.latitude,
                    lng: pos.coords.longitude
                }
            })
        });

        const result = await response.json();
        if (result.result && result.result.success) {
            alert("Checkpoint logged successfully!");
            window.location.reload();
        } else {
            alert(result.result.error || "Error logging checkpoint");
        }
    } catch (err) {
        alert("GPS access required.");
    }
}

async function startScanner(code) {
    if (scanning) return;
    currentCode = code;
    video.style.display = 'block';
    scanning = true;

    try {
        const stream = await navigator.mediaDevices.getUserMedia({ video: { facingMode: 'environment' } });
        video.srcObject = stream;

        const canvas = document.createElement('canvas');
        const ctx = canvas.getContext('2d');

        const loop = async () => {
            if (!scanning) return;
            if (video.readyState === video.HAVE_ENOUGH_DATA) {
                canvas.height = video.videoHeight;
                canvas.width = video.videoWidth;
                ctx.drawImage(video, 0, 0, canvas.width, canvas.height);
                const imageData = ctx.getImageData(0, 0, canvas.width, canvas.height);
                const qr = jsQR(imageData.data, imageData.width, imageData.height, { inversionAttempts: "dontInvert" });
                if (qr && qr.data === currentCode) {
                    scanning = false;
                    await logCheckpoint(qr.data);
                    stopScanner();
                }
            }
            requestAnimationFrame(loop);
        };
        loop();
    } catch (err) {
        alert("Camera not accessible or permissions denied.");
        stopScanner();
    }
}

  // Attach click event after a small delay to ensure DOM is ready
  setTimeout(function(){
      document.querySelectorAll('.scan-btn').forEach(function(btn) {
          btn.addEventListener('click', function() {
              var code = btn.getAttribute('data-code');
              startScanner(code);
          });
      });
  }, 1000);
